/* text styles in banner module */
.large-content-text {
  font-size: 1.5rem;
  line-height: 2rem;
  margin-bottom: 1rem;
}

.small-content-text {
  font-size: 1rem;
  line-height: 1.5rem;
  margin-bottom: 0.5rem;
}

.honeycomb .bullet-to-tick ul li {
  list-style-type: "✔ " !important;
  padding-left: 0.5rem;
}

/* standard padding for most of the module containers under each break point */
.standard-spacing {
  padding: 4rem;
}
@media (max-width: 1139px) {
  .standard-spacing {
    padding: 3rem;
  }
}
@media (max-width: 977px) {
  .standard-spacing {
    padding: 3rem 2rem;
  }
}
@media (max-width: 767px) {
  .standard-spacing {
    padding: 3rem 1.5rem;
  }
}

/* for module containers to toggle the bottom divider line */
.bottom-divider {
  position: relative;
}
.bottom-divider::after {
  content: " ";
  display: block;
  position: absolute;
  height: 1px;
  width: calc(100% - 8rem);
  right: 4rem;
  bottom: 0;
  background: #e9e9e9;
}
@media (max-width: 977px) {
  .bottom-divider::after {
    width: calc(100% - 5rem);
    right: 2.5rem;
  }
}
@media (max-width: 767px) {
  .bottom-divider::after {
    width: calc(100% - 3rem);
    right: 1.5rem;
  }
}

/* ensure hero image for each module is not causing horizontal scrolls */
.container-fluid {
  overflow-x: hidden;
}

/* breadcrumb - part of the template, leave it into layout for now */
@media (max-width: 977px) {
  .content-breadcrumb .breadcrumb {
    display: none;
  }
}
.content-breadcrumb .breadcrumb {
  margin: 0;
  position: absolute;
  z-index: 1;
  left: 5rem;
  top: 0;
  line-height: 1.5rem;
  font-size: 14px;
  padding: 1.75rem 2rem 1.75rem 0;
  width: calc(50% - 12.5rem);
  white-space: nowrap;
  text-overflow: ellipsis;
  overflow: hidden;
}

/* Screen reader only - allows to read override content */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* Border targeting */
.border-targeting {
  border: 0.125rem solid #54c2e8;
}

.js-hollard-chat-config {
  display: none !important;
  width: 0;
  height: 0;
  overflow: hidden;
  position: absolute;
  pointer-events: none;
}

.visually-hidden {
  border: 0;
  clip: rect(0 0 0 0);
  height: 1px;
  margin: -1px;
  overflow: hidden;
  padding: 0;
  position: absolute;
  width: 1px;
}

/* Remove margin and padding bottom of last row of an module.
This mixin is not suitable for module which has unbalanced columns */
/* For 2/3/4 columns layout */
@keyframes fadeInDown {
  from {
    opacity: 0;
    top: calc(-3rem - 5%);
  }
  to {
    opacity: 1;
    top: 0;
  }
}
@keyframes fadeInUp {
  from {
    opacity: 0;
    top: 3rem;
  }
  to {
    opacity: 1;
    top: 0;
  }
}
@keyframes fadeFromDown {
  from {
    opacity: 0;
    bottom: -3rem;
  }
  to {
    opacity: 1;
  }
}
