/* For 2/3/4 columns layout */
@keyframes fadeInDown {
  from {
    opacity: 0;
    top: calc(-48px - 5%);
  }
  to {
    opacity: 1;
    top: 0;
  }
}
@keyframes fadeInUp {
  from {
    opacity: 0;
    top: 48px;
  }
  to {
    opacity: 1;
    top: 0;
  }
}
@keyframes fadeFromDown {
  from {
    opacity: 0;
    bottom: -48px;
  }
  to {
    opacity: 1;
  }
}
