/* Iguana banner style */
.iguana-banner--module,
.honeycomb .iguana-banner--module {
  padding-top: 80px;
  position: relative;
  background: #fff;
}
@media (max-width: 977px) {
  .iguana-banner--module,
  .honeycomb .iguana-banner--module {
    padding: 0;
  }
}
.iguana-banner--module .banner-content-panel,
.honeycomb .iguana-banner--module .banner-content-panel {
  padding: 32px 0 64px 0;
  margin-bottom: 0;
  width: 100%;
  min-height: auto;
}
@media (max-width: 977px) {
  .iguana-banner--module .banner-content-panel,
  .honeycomb .iguana-banner--module .banner-content-panel {
    padding: 32px 0;
  }
}
.iguana-banner--module .banner-content,
.honeycomb .iguana-banner--module .banner-content {
  padding: 0 64px;
  width: 70%;
  border-left: 16px solid #fc0;
}
@media (max-width: 1139px) {
  .iguana-banner--module .banner-content,
  .honeycomb .iguana-banner--module .banner-content {
    padding: 0 48px;
    width: 80%;
  }
}
@media (max-width: 977px) {
  .iguana-banner--module .banner-content,
  .honeycomb .iguana-banner--module .banner-content {
    padding: 0 24px;
    width: 100%;
    border-left: 8px solid #fc0;
  }
}
@media (max-width: 767px) {
  .iguana-banner--module .banner-content,
  .honeycomb .iguana-banner--module .banner-content {
    padding: 0 16px;
  }
}
.iguana-banner--module .banner-content h1,
.honeycomb .iguana-banner--module .banner-content h1 {
  margin-bottom: 16px;
  font-size: 56px;
  line-height: 64px;
}
@media (max-width: 977px) {
  .iguana-banner--module .banner-content h1,
  .honeycomb .iguana-banner--module .banner-content h1 {
    font-size: 24px;
    line-height: 32px;
  }
}
.iguana-banner--module .banner-content p,
.honeycomb .iguana-banner--module .banner-content p {
  margin-bottom: 0;
}

