.feedback-module .feedback-wrapper p,
.honeycomb .feedback-module .feedback-wrapper p {
  margin: 0 1.5rem 0 0;
  display: inline-block;
  line-height: 1.5rem;
  font-weight: bold;
}
@media (max-width: 977px) {
  .feedback-module .feedback-wrapper p,
  .honeycomb .feedback-module .feedback-wrapper p {
    display: block;
    margin-bottom: 1rem;
  }
}
.feedback-module .feedback-wrapper button,
.honeycomb .feedback-module .feedback-wrapper button {
  background-color: #fff;
  min-width: 120px;
  margin-right: 1rem;
}
@media (max-width: 767px) {
  .feedback-module .feedback-wrapper button,
  .honeycomb .feedback-module .feedback-wrapper button {
    min-width: 100%;
    width: 100%;
    margin-bottom: 1rem;
    text-align: center;
  }
}
.feedback-module .feedback-wrapper button span,
.honeycomb .feedback-module .feedback-wrapper button span {
  text-align: right;
  padding-left: 2rem;
  display: inline-block;
}
.feedback-module .feedback-wrapper button.thumb-up span,
.honeycomb .feedback-module .feedback-wrapper button.thumb-up span {
  background: url(/aem-assets/resources/ThumbUp32.png) no-repeat;
  background-position: 15% 47%;
}
.feedback-module .feedback-wrapper button.thumb-down span,
.honeycomb .feedback-module .feedback-wrapper button.thumb-down span {
  background: url(/aem-assets/resources/ThumbDown32.png) no-repeat;
  background-position: 15% 56%;
}
.feedback-module .feedback-wrapper button.disabled,
.honeycomb .feedback-module .feedback-wrapper button.disabled {
  background-color: #D3D2D2;
}
.feedback-module .show-message,
.honeycomb .feedback-module .show-message {
  display: block;
  margin-top: 16px;
}
.feedback-module .hide-message,
.honeycomb .feedback-module .hide-message {
  display: none;
}
.feedback-module.top-border, .feedback-module.bottom-border,
.honeycomb .feedback-module.top-border,
.honeycomb .feedback-module.bottom-border {
  padding-left: 0;
  padding-right: 0;
  margin-left: 64px;
  margin-right: 64px;
}
.feedback-module.bottom-border,
.honeycomb .feedback-module.bottom-border {
  border-bottom: 1px solid #e9e9e9;
}
.feedback-module.top-border,
.honeycomb .feedback-module.top-border {
  border-top: 1px solid #e9e9e9;
}

/* Remove margin and padding bottom of last row of an module.
This mixin is not suitable for module which has unbalanced columns */
/* For 2/3/4 columns layout */
@keyframes fadeInDown {
  from {
    opacity: 0;
    top: calc(-48px - 5%);
  }
  to {
    opacity: 1;
    top: 0;
  }
}
@keyframes fadeInUp {
  from {
    opacity: 0;
    top: 48px;
  }
  to {
    opacity: 1;
    top: 0;
  }
}
@keyframes fadeFromDown {
  from {
    opacity: 0;
    bottom: -48px;
  }
  to {
    opacity: 1;
  }
}
