.tabs {
  position: relative;
}
.tabs .mobile {
  display: none;
}
.tabs .cmp-tabs__tablist {
  border-bottom: 1px solid #e9e9e9;
  list-style: none;
}
.tabs .cmp-tabs__tablist .cmp-tabs__tab {
  padding: 12px 50px;
  color: #706f6d;
  white-space: nowrap;
}
.tabs .cmp-tabs__tablist .cmp-tabs__tab.cmp-tabs__tab--active {
  margin-bottom: 0;
  border-bottom-color: #000;
  border-bottom-width: 2px;
  color: #1e1e1e;
  font-weight: 700;
}
.tabs .cmp-tabs.tabs-container .scroll-left,
.tabs .cmp-tabs.tabs-container .scroll-right {
  position: absolute;
  background: #fff;
  border: 2px solid #000;
  cursor: pointer;
  z-index: 1;
  top: 10px;
  width: 48px;
  height: 48px;
  display: none;
  -webkit-box-align: end;
      -ms-flex-align: end;
          align-items: end;
  -webkit-box-pack: center;
      -ms-flex-pack: center;
          justify-content: center;
  font-size: 34px;
  border-radius: 0;
  color: #000;
}
.tabs .cmp-tabs.tabs-container .scroll-left {
  left: 0;
}
.tabs .cmp-tabs.tabs-container .scroll-right {
  right: 0;
}
.tabs .cmp-tabs.tabs-container .scroll-container {
  overflow-x: auto;
  white-space: nowrap;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
}
@media screen and (max-width: 768px) {
  .tabs {
    /* Dropdown styles */
  }
  .tabs .cmp-tabs__tablist {
    display: -webkit-box;
    display: -ms-flexbox;
    display: flex;
    overflow-x: scroll;
    -ms-flex-wrap: nowrap;
        flex-wrap: nowrap;
    margin-bottom: 0;
    -ms-scroll-snap-type: x mandatory;
        scroll-snap-type: x mandatory;
    scrollbar-width: none;
    width: calc(100% - 100px);
    justify-self: center;
    padding-left: 0;
  }
  .tabs .cmp-tabs__tablist .cmp-tabs__tab {
    padding: 12px 50px 20px 50px;
    scroll-snap-stop: always;
    scroll-snap-align: start;
    margin-bottom: 0;
  }
  .tabs::-webkit-scrollbar {
    display: none;
  }
  .tabs .cmp-tabs.tabs-container .scroll-left,
  .tabs .cmp-tabs.tabs-container .scroll-right {
    display: -webkit-box;
    display: -ms-flexbox;
    display: flex;
  }
}

/* Remove margin and padding bottom of last row of an module.
This mixin is not suitable for module which has unbalanced columns */
/* For 2/3/4 columns layout */
@keyframes fadeInDown {
  from {
    opacity: 0;
    top: calc(-48px - 5%);
  }
  to {
    opacity: 1;
    top: 0;
  }
}
@keyframes fadeInUp {
  from {
    opacity: 0;
    top: 48px;
  }
  to {
    opacity: 1;
    top: 0;
  }
}
@keyframes fadeFromDown {
  from {
    opacity: 0;
    bottom: -48px;
  }
  to {
    opacity: 1;
  }
}
